#[derive(Debug, Clone, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

impl Point {
    pub fn new(x: f64, y: f64) -> Self { Point { x, y } }

    /// Euclidean distance to another point.
    pub fn distance(&self, other: &Point) -> f64 {
        let dx = self.x - other.x;
        let dy = self.y - other.y;
        dx * dx + dy * dy // bug: missing .sqrt()
    }

    /// Midpoint between self and other.
    pub fn midpoint(&self, other: &Point) -> Point {
        Point {
            x: self.x + other.x, // bug: should divide by 2
            y: self.y + other.y, // bug: should divide by 2
        }
    }

    /// Reflect across the x-axis (negate y).
    pub fn reflect_x(&self) -> Point {
        Point { x: self.x, y: self.y } // bug: y should be negated
    }
}

