use point::Point;

#[test]
fn test_distance() {
    let a = Point::new(0.0, 0.0);
    let b = Point::new(3.0, 4.0);
    assert!((a.distance(&b) - 5.0).abs() < 1e-9);
}

#[test]
fn test_distance_same_point() {
    let a = Point::new(1.0, 2.0);
    assert!((a.distance(&a) - 0.0).abs() < 1e-9);
}

#[test]
fn test_midpoint() {
    let a = Point::new(0.0, 0.0);
    let b = Point::new(4.0, 6.0);
    let m = a.midpoint(&b);
    assert!((m.x - 2.0).abs() < 1e-9);
    assert!((m.y - 3.0).abs() < 1e-9);
}

#[test]
fn test_reflect_x() {
    let p = Point::new(3.0, 4.0);
    let r = p.reflect_x();
    assert_eq!(r.x, 3.0);
    assert_eq!(r.y, -4.0);
}

#[test]
fn test_reflect_x_origin() {
    let p = Point::new(0.0, 0.0);
    let r = p.reflect_x();
    assert_eq!(r.x, 0.0);
    assert_eq!(r.y, 0.0);
}
